mapper.select:
SELECT COUNT(1) FROM assess_mgmt
WHERE deleted = 0

    AND grade = #{grade}


    AND major = #{major}


    AND assess_type = #{assessType}


    AND status = #{status}

SELECT AVG(score) FROM assess_mgmt
WHERE deleted = 0

    AND grade = #{grade}


    AND major = #{major}


    AND assess_type = #{assessType}


    AND status = #{status}

SELECT COUNT(1) FROM assess_mgmt
WHERE deleted = 0 AND status = '已发布' AND publish_time >= DATE(NOW()) AND publish_time < DATE(NOW())

    AND grade = #{grade}


    AND major = #{major}

SELECT assess_type AS name, COUNT(1) AS count FROM assess_mgmt WHERE deleted = 0 AND status = '已发布'
AND grade = #{grade}
GROUP BY assess_type

SELECT DATE(create_time) AS date, COUNT(1) AS newAssessCount,
COUNT(IF(status = '已发布', 1, NULL)) AS publishCount
FROM assess_mgmt
WHERE deleted = 0

    AND grade = #{grade}

AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY DATE(create_time)
ORDER BY DATE(create_time) ASC
